ps.pstext:
if !(IsFeatureImplemented(FEAT_SEL2) && IsFeatureImplemented(FEAT_AA64)) then
    Undefined();
elsif PSTATE.EL == EL0 then
    Undefined();
elsif PSTATE.EL == EL1 then
    if !IsCurrentSecurityState(SS_Secure) then
        Undefined();
    elsif EffectiveHCR_EL2_NVx() IN {'xx1'} then
        AArch64_SystemAccessTrap(EL2, 0x18);
    else
        Undefined();
    end;
elsif PSTATE.EL == EL2 then
    if !IsCurrentSecurityState(SS_Secure) then
        Undefined();
    else
        X{64}(t) = CNTHPS_CTL_EL2();
    end;
elsif PSTATE.EL == EL3 then
    if SCR_EL3().EEL2 == '0' then
        Undefined();
    else
        X{64}(t) = CNTHPS_CTL_EL2();
    end;
end;

if !(IsFeatureImplemented(FEAT_SEL2) && IsFeatureImplemented(FEAT_AA64)) then
    Undefined();
elsif PSTATE.EL == EL0 then
    Undefined();
elsif PSTATE.EL == EL1 then
    if !IsCurrentSecurityState(SS_Secure) then
        Undefined();
    elsif EffectiveHCR_EL2_NVx() IN {'xx1'} then
        AArch64_SystemAccessTrap(EL2, 0x18);
    else
        Undefined();
    end;
elsif PSTATE.EL == EL2 then
    if !IsCurrentSecurityState(SS_Secure) then
        Undefined();
    else
        CNTHPS_CTL_EL2() = X{64}(t);
    end;
elsif PSTATE.EL == EL3 then
    if SCR_EL3().EEL2 == '0' then
        Undefined();
    else
        CNTHPS_CTL_EL2() = X{64}(t);
    end;
end;

if !IsFeatureImplemented(FEAT_AA64) then
    Undefined();
elsif PSTATE.EL == EL0 then
    if EffectivelyAtEL0NotInHost() && CNTKCTL_EL1().EL0PTEN == '0' then
        AArch64_SystemAccessTraptoEL1orEL2(0x18);
    elsif EL2Enabled() && !ELIsInHost(EL2) && CNTHCTL_EL2().EL1PCEN == '0' then
        AArch64_SystemAccessTrap(EL2, 0x18);
    elsif ELIsInHost(EL2) && EffectiveTGEforEL0Traps() == '0' && CNTHCTL_EL2().EL1PTEN == '0' then
        AArch64_SystemAccessTrap(EL2, 0x18);
    elsif EffectivelyAtEL0InHost() && CNTHCTL_EL2().EL0PTEN == '0' then
        AArch64_SystemAccessTrap(EL2, 0x18);
    elsif EffectivelyAtEL0InHost() && IsCurrentSecurityState(SS_Secure) && IsFeatureImplemented(FEAT_SEL2) then
        X{64}(t) = CNTHPS_CTL_EL2();
    elsif EffectivelyAtEL0InHost() && !IsCurrentSecurityState(SS_Secure) then
        X{64}(t) = CNTHP_CTL_EL2();
    else
        X{64}(t) = CNTP_CTL_EL0();
    end;
elsif PSTATE.EL == EL1 then
    if EL2Enabled() && !ELIsInHost(EL2) && CNTHCTL_EL2().EL1PCEN == '0' then
        AArch64_SystemAccessTrap(EL2, 0x18);
    elsif ELIsInHost(EL2) && CNTHCTL_EL2().EL1PTEN == '0' then
        AArch64_SystemAccessTrap(EL2, 0x18);
    elsif EffectiveHCR_EL2_NVx() IN {'111'} then
        X{64}(t) = NVMem(0x180);
    else
        X{64}(t) = CNTP_CTL_EL0();
    end;
elsif PSTATE.EL == EL2 then
    if ELIsInHost(EL2) && IsCurrentSecurityState(SS_Secure) && IsFeatureImplemented(FEAT_SEL2) then
        X{64}(t) = CNTHPS_CTL_EL2();
    elsif ELIsInHost(EL2) && !IsCurrentSecurityState(SS_Secure) then
        X{64}(t) = CNTHP_CTL_EL2();
    else
        X{64}(t) = CNTP_CTL_EL0();
    end;
elsif PSTATE.EL == EL3 then
    X{64}(t) = CNTP_CTL_EL0();
end;

if !IsFeatureImplemented(FEAT_AA64) then
    Undefined();
elsif PSTATE.EL == EL0 then
    if EffectivelyAtEL0NotInHost() && CNTKCTL_EL1().EL0PTEN == '0' then
        AArch64_SystemAccessTraptoEL1orEL2(0x18);
    elsif EL2Enabled() && !ELIsInHost(EL2) && CNTHCTL_EL2().EL1PCEN == '0' then
        AArch64_SystemAccessTrap(EL2, 0x18);
    elsif ELIsInHost(EL2) && EffectiveTGEforEL0Traps() == '0' && CNTHCTL_EL2().EL1PTEN == '0' then
        AArch64_SystemAccessTrap(EL2, 0x18);
    elsif EffectivelyAtEL0InHost() && CNTHCTL_EL2().EL0PTEN == '0' then
        AArch64_SystemAccessTrap(EL2, 0x18);
    elsif EffectivelyAtEL0InHost() && IsCurrentSecurityState(SS_Secure) && IsFeatureImplemented(FEAT_SEL2) then
        CNTHPS_CTL_EL2() = X{64}(t);
    elsif EffectivelyAtEL0InHost() && !IsCurrentSecurityState(SS_Secure) then
        CNTHP_CTL_EL2() = X{64}(t);
    else
        CNTP_CTL_EL0() = X{64}(t);
    end;
elsif PSTATE.EL == EL1 then
    if EL2Enabled() && !ELIsInHost(EL2) && CNTHCTL_EL2().EL1PCEN == '0' then
        AArch64_SystemAccessTrap(EL2, 0x18);
    elsif ELIsInHost(EL2) && CNTHCTL_EL2().EL1PTEN == '0' then
        AArch64_SystemAccessTrap(EL2, 0x18);
    elsif EffectiveHCR_EL2_NVx() IN {'111'} then
        NVMem(0x180) = X{64}(t);
    else
        CNTP_CTL_EL0() = X{64}(t);
    end;
elsif PSTATE.EL == EL2 then
    if ELIsInHost(EL2) && IsCurrentSecurityState(SS_Secure) && IsFeatureImplemented(FEAT_SEL2) then
        CNTHPS_CTL_EL2() = X{64}(t);
    elsif ELIsInHost(EL2) && !IsCurrentSecurityState(SS_Secure) then
        CNTHP_CTL_EL2() = X{64}(t);
    else
        CNTP_CTL_EL0() = X{64}(t);
    end;
elsif PSTATE.EL == EL3 then
    CNTP_CTL_EL0() = X{64}(t);
end;
